{
  "teaching_material": {
    "knowledge_point": "Earth's Layers",
    "grade_level": "Middle School (Grade 7-8)",
    "duration": "45 minutes",
    "teaching_objectives": [
      {
        "category": "Knowledge",
        "description": "Students will be able to identify and list the four main layers of the Earth (Crust, Mantle, Outer Core, Inner Core) and describe their approximate compositions and states (solid/liquid)."
      },
      {
        "category": "Skills",
        "description": "Students will demonstrate understanding of how scientists determine Earth's layers using seismic waves and data from earth-quakes."
      },
      {
        "category": "Attitude",
        "description": "Students will appreciate the scientific methods used to study Earth's interior without being able to drill deep into it, fostering curiosity about planetary science."
      }
    ],
    "key_points": [
      "The four distinct layers of the Earth: Crust, Mantle, Outer Core, Inner Core.",
      "Composition differences: Crust/Mantle (Rock/Silicates) vs. Cores (Iron/Nickel).",
      "State differences: Mantle is solid pliable, Outer Core is liquid, Inner Core is solid due to extreme pressure.",
      "Significance: How layers influence plate tectonics and magnetic field generation."
    ],
    "teaching_difficulties": [
      "Understanding that the Inner Core is solid despite the extremely high temperatures (internal pressure vs. temperature dynamics).",
      "Grasping the evidence from Seismic Waves (P-waves and S-waves) that allows us to detect the boundaries between layers.",
      "Dealing with the concept of density increasing significantly as one goes deeper."
    ],
    "teaching_materials": [
      "Diagram of Earth's Cross-Section",
      "Video clip: 'What is Inside the Earth?' (NASA/Science Channel)",
      "Seismic Wave Simulation App or Props (balls/springs)",
