      },
      "phase_4_conclusion": {
        "activity": "Review and Assessment",
        "steps": [
          "Quick-fire questions on the layers.",
          "Group representatives explain their models.",
          "Connect to Earth's magnetic field generated by the liquid Outer Core.",
          "Homework assignment distribution."
        ],
        "duration_minutes": 10
      }
    },
    "homework_assignment": {
      "task": "Research and Present",
      "description": "Find a picture of a volcano or earthquake. Research why the tectonic plates move at the boundaries of the Mantle. Write a one-page summary.",
