      "Compare quantity competition (Cournot) and price competition (Bertrand) models.",
      "Analyze the stability of collusive agreements in repeated games."
    ],
    "key_points": [
      {
        "concept": "Strategic Interdependence",
        "description": "The realization that one firm's decision affects others' payoffs and vice versa, unlike perfect competition.",
        "example": "If Firm A cuts price, Firm B must respond to avoid losing market share."
      },
      {
        "concept": "Nash Equilibrium",
        "description": "No player has an incentive to deviate from their chosen strategy after considering an opponent's choice.",
        "example": "In the Prisoner's Dilemma, both confessing is the Nash Equilibrium."
      },
      {
        "concept": "Cournot Competition",
        "description": "Direct quantity competition where firms choose output levels simultaneously to maximize profit given rival output.",
        "example": "Oil producers adjusting production quotas."
      },
      {
        "concept": "Bertrand Competition",
        "description": "Price competition where firms choose prices simultaneously, leading to margin erosion.",
        "example": "Competitive airline pricing or soda pricing."
      },
      {
        "concept": "Cartels and Collusion",
        "description": "Repeated interaction allowing firms to tacitly agree to restrict output/rail increase prices for higher profits.",
        "example": "OPEC and its member states' oil production agreements."
      }
    ],
    "difficulties": [
