{
  "teaching_material": {
    "topic": "The Doctrine of Stare Decisis in Common Law Systems",
    "target_audience": "Undergraduate Law Students / First-Year Legal Professionals",
    "duration_minutes": 90,
    "section_1": {
      "field": "teaching_objectives",
      "value": [
        "Define stare decisis and explain its literal Latin meaning.",
        "Identify the hierarchy of courts regarding binding and persuasive authority in common law jurisdictions.",
        "Analyze the rationale for stare decisis, including consistency, predictability, and fairness.",
        "Evaluate the exceptions to the rule, specifically the ability to distinguish or overrule precedent.",
        "Critically assess the tension between legal stability and social change through the doctrine."
      ]
    },
    "section_2": {
      "field": "key_points",
      "value": [
        "Etymology: Stare decisis ('to stand by things decided') establishes judicial consistency.",
        "Hierarchy of Authority: Decisions from higher courts bind lower courts vertically; decisions with similar facts bind other courts horizontally.",
        "Rationale: Predictability allows litigants and parties to understand legal consequences; stability maintains public confidence.",
        "Types of Precedent: Stare decisis applies to ratio decidendi (the ratio of the decision), whereas obiter dicta (side remarks) are non-binding.",
        "Exceptions: Courts may overrule precedent if it has been recognized as erroneous (e.g., by a higher court) or if a social change alters the original rationale."
      ]
    },
    "section_3": {
      "field": "teaching_difficulties",
      "value": [
        "Distinguishing between binding precedent and persuasive authority in cross-jurisdictional contexts.",
        "Understanding the procedural requirements for the Supreme Court to overrule its own precedent.",
        "Applying the concept of distinguishing facts to modify outcomes in similar cases.",
        "Balancing the perceived unfairness of rigid adherence with the need for progressive legal evolution."
      ]
    },
    "section_4": {
      "field": "classroom_activities",
      "value": [
        {
          "activity_name": "Case Comparison Analysis",
          "description": "Provide students with two similar case fact patterns. In Case A, the outcome follows existing precedent. In Case B, the court applies a distinguishing factor to reach a similar result. Students must write an opinion explaining why the legal reasoning differs despite the factual similarity.",
          "duration_minutes": 20
        },
        {
          "activity_name": "Role Play: The Judge's Dilemma",
          "description": "Divide the class into groups. One student acts as the current judge, one as counsel for the plaintiff, and one as the appellate court. The scenario involves a new social issue requiring a ruling on a precedent established 50 years ago. Groups must debate whether to follow or overrule the old rule.",
          "duration_minutes": 25
        },
        {
          "activity_name": "Debate: Stability vs. Progress",
          "description": "Split class into positive and negative teams debating the proposition: \"Stare decisis is essential for a fair legal system compared to the alternative of law changing with every decision.\" Teams must cite at least two historical legal precedents to support their stance.",
          "duration_minutes": 25
        }
      ]
    },
    "section_5": {
      "field": "assessment_methods",
      "value": [
        "Short written quiz focusing on court hierarchy and correct terminology.",
        "Individual essay accompanying assigned reading case analysis on the pros and cons of overruling precedent.",
        "Peer review of the Role Play presentation rubric based on argument logic and legal citation accuracy."
      ]
    }
  }
}

