      "estimated_duration": "90 minutes",
      "target_audience": "Undergraduate Community/Public Policy Program"
    },
    "teaching_objectives": {
      "knowledge": "Students will understand the definition, principles, and steps of Cost-Benefit Analysis (CBA) in policy evaluation.",
