      "attitude": "Students will develop critical awareness of the ethical and political complexities associated with monetizing public goods and social costs."
    },
    "content_outline": {
      "key_points": [
        {
          "point": "Definition and Scope",
          "detail": "CBA is a systematic approach to measuring the overall effects of a policy decision on society in terms of money."
        },
        {
          "point": "Quantifying Benefits and Costs",
          "detail": "Identifying monetizable items (income) and non-monetable items via shadow pricing (e.g., clean air, time savings)."
        },
        {
          "point": "Discounting and Time Value",
          "detail": "Accounting for the time value of money using discount rates to calculate Present Value (PV)."
        }
      ],
      "difficulties": [
        {
          "difficulty": "Valuing Intangibles",
          "explanation": "Assigning monetary value to things like quality of life, human life, or environmental aesthetics."
        },
        {
          "difficulty": "Data Uncertainty",
          "explanation": "Long-term policy outcomes (e.g., climate effect) are difficult to predict accurately; stochastic modeling is required."
        },
        {
          "difficulty": "Distributional Effects",
          "explanation": "CBA often fails to account for how the costs/benefits are distributed across different income groups or demographics."
        }
      ]
    },
    "teaching_methods": [
      "Lecture",
      "Case Study Analysis",
      "Group Discussion",
      "Quantitative Workshop"
    ],
    "classroom_activity_design": {
