      "activity_steps": [
        "Step 1: Preparation",
        {
          "task": "Prepare a deck of cards: one set labeled 'Sulbactam Resistant' (blue print), one set 'Sulbactam Sensitive' (red print). Prepare 'Antibiotic Injection' cards."
        },
        "Step 2: Simulation",
        {
          "task": "Each student group represents a 'bacterial colony'. They must pass a 'resistance' card to 'mimic' horizontal gene transfer events."
        },
        "Step 3: The Challenge",
        {
          "task": "In phase one, no resistance is present. After using the 'Antibiotic Card', the sensitive bacteria die. In phase two, 'resistant' bacteria emerge."
        },
        "Step 4: Discussion",
        {
          "task": "Groups explain why the resistance spread and use their cards to model the specific mechanisms (enzymes, changes, pumps)."
