      "pre_class": {
        "task": "Students review 10 scientific papers identifying common patterns in TME analysis.",
        "delivery": "Digital reading before lecture."
      },
      "in_class_stages": [
        {
          "phase": "Introduction",
          "method": "Lecture with visual aids: Comparative macroscopic image of normal tissue vs. tumor tissue secretion.",
          "duration": "15 mins"
        },
        {
          "phase": "Core Concept",
          "method": "Interactive Slide Deck. Animate signaling pathways (PD-L1, VEGF, Wnt) using digital whiteboard.",
          "duration": "20 mins"
        },
