      "duration": "90 minutes (2 class periods)",
      "level": "Intermediate"
    },
    "teaching_objectives": {
      "knowledge": [
        "Define social stratification and distinguish it from social mobility.",
        "Identify the Three Main Types of Stratification Systems: Caste, Class, and Meritocracy.",
        "Explain Weberian concepts of Class, Status, and Party/Power.",
        "Understand capital-based inequality within Marxist theory."
      ],
      "skill": [
        "Analyze case studies to identify stratification mechanisms in given scenarios.",
        "Evaluate data regarding income and wealth inequality using graphical representations.",
        "Apply sociological theories to contemporary news articles."
      ],
      "affective": [
        "Reduce stigma associated with class status analysis.",
        "Develop awareness of privilege and inequity in educational and economic settings."
      ]
    },
    "key_points": [
      {
        "concept": "Social Stratification",
        "definition": "The organized hierarchy of positions in a society based on the possession of valued resources."
      },
      {
        "concept": "Fluid Class Systems",
        "definition": "Systems where status is open, based on achievement and economic resources, allowing for social mobility."
      },
      {
        "concept": "Weber's Three Dimensions",
        "definition": "Class (Economic opportunities/Income), Status (Social prestige), and Power (Political control).",
        "import": "Clarifies that money does not always equal influence."
      },
      {
        "concept": "Functonalism vs Conflict Theory",
        "definition": "Functonalism: Stratification is necessary for filling scarce positions; Conflict Theory: Inequality is a tool to subordinate the working class."
      }
    ],
    "teaching_difficulties": [
      {
        "difficulty": "Concept of Power",
        "explanation": "Students often confuse economic wealth with political power or social status. Need mechanisms to differentiate."
      },
      {
        "difficulty": "Subjectivity of Class",
        "explanation": "How does an individual perceive their own class status? Personal identity vs. structural reality."
      },
      {
        "difficulty": "Abstract Theoretical Application",
        "explanation": "Applying abstract frameworks like Durkheim or Marx to understanding modern digital socioeconomic structures."
      }
    ],
    "classroom_activity_design": {
