      "activity_type": "Problem-based Visual Analysis & Roleplay",
      "duration": "45 minutes",
      "duration_breakdown": {
        "intro": "10 minutes",
        "simulation": "25 minutes",
        "debrief": "10 minutes"
      },
      "materials_needed": [
        "Access to a public dataset on income/wealth by region (e.g., U.S. Census data)",
        "Whiteboard/Smart Board",
        "Large Sheet of Paper (for ranking)",
        "Markers"
      ],
      "steps": [
        {
          "step_number": 1,
          "title": "Introduction",
          "description": "Define social stratification. Ask students if they understand what 'class' means. Introduce Caste vs. Class systems."
        },
        {
          "step_number": 2,
          "title": "Data Visualization",
          "description": "Provide chart showing wealth distribution across three fictional classes (Low, Middle, High). Ask students to interpret inter-generational mobility rates."
        },
        {
          "step_number": 3,
          "title": "Student Simulation",
          "description": "Divide class into groups. Give each group a specific starting budget or skillset representing a class position. Ask them to simulate gaining resources over 3 rounds (simulating educational/opportunities). Track overall mobility outcomes."
        },
        {
          "step_number": 4,
          "title": "Debrief",
