        "time_period": "Childhood to Adulthood"
      },
      {
        "agent": "Peer Group",
        "description": "Socializes through interaction with same-age individuals; crucial for identity formation, conformity, and leadership skills.",
        "time_period": "Adolescence and Adulthood"
      },
      {
        "agent": "Mass Media",
        "description": "Modern agent; shapes perspectives, ideals, and behaviors through print, television, and internet.",
        "time_period": "Throughout Life"
      },
      {
        "agent": "Workplace",
        "description": "Initiates formal socialization; employers teach norms, etiquette, and professional roles.",
        "time_period": "Adulthood"
      }
    ],
