        "duration": "15 Mins"
      },
      "main_lesson_2": {
        "name": "Role-Play Scenario: The Career Interview",
        "description": "Student groups enact a job interview to observe workplace socialization and observe how 'agents of work' apply rules and expectations.",
        "duration": "20 Mins"
      },
      "main_lesson_3": {
        "name": "Debating the Media's Role",
