{
  "course_info": {
    "subject": "Social Psychology",
    "level": "Undergraduate",
    "duration": "2 hours",
    "topic": "Cognitive Dissonance Theory"
  },
  "knowledge_point": {
    "name": "Cognitive Dissonance Theory",
    "proposer": "Leon Festinger (1957)",
    "definition": "The psychological discomfort experienced by an individual who holds two or more contradictory beliefs, ideas, or values; or who performs an action that is inconsistent with their beliefs."
  },
  "teaching_objectives": [
    {
      "type": "Knowledge",
      "content": "Define Cognitive Dissonance Theory and explain the core concept of psychological discomfort caused by inconsistency."
    },
    {
      "type": "Skill",
      "content": "Analyze real-life scenarios to identify instances of cognitive dissonance."
    },
    {
      "type": "Attitude",
      "content": "Understand the importance of cognitive consistency to enhance critical thinking and self-awareness."
    }
  ],
  "teaching_resources": [
    "Video: 'The Battle of Beliefs' (3 MIN)",
    "Textbook Chapter: Festinger and Caughlin Research",
    "Real-world Case Studies (Social Media, Consumer Behavior, Health)",
    "Handouts: Cognitive Dissonance Worksheet"
  ],
  "key_points": [
    "Definition and origin of Cognitive Dissonance Theory.",
    "The three primary mechanisms to reduce dissonance: changing attitude, changing behavior, adding consonant information.",
    "The 'Induced Compliance' experiments (Forced Compliance Paradigm) demonstrating magnitude of dissonance reduction.",
    "Application to everyday behavior (Consumerism, Health Behaviors, Moral Dilemmas)."
  ],
  "difficulties": [
    "Understanding the psychological process of self-regulation above and beyond simple motivation.",
    "Distinguishing between mere attitude inconsistency and the emotional discomfort of dissonance.",
    "Applying theory to complex, ambiguous real-world situations where dissonance may not be immediately visible."
  ],
  "classroom_activities": [
    {
      "activity_id": 1,
      "name": "Reflection and Identification",
      "description": "Students are asked to write down a personal situation where they doubt their own judgment. Example: Buying a health product while knowing it's ineffective. They discuss how they rationalize the choice.",
      "duration_minutes": 15
    },
    {
      "activity_id": 2,
      "name": "Group Case Study",
      "description": "Divide class into small groups. Each group analyzes a specific scenario (e.g., Traffic Smashing, Smoking, veganism vs. burgers). They must identify the specific dissonant elements and propose how the individual resolves them (change belief, change behavior, etc.).",
      "duration_minutes": 20
    },
    {
      "activity_id": 3,
      "name": "Simulation Discussion",
      "description": "Teacher presents a hypothetical situation where a student must make a commitment inconsistent with their values (e.g., Choosing an passable career path despite high costs for support). Discuss the psychological pressure involved in that choice.",
      "duration_minutes": 20
    },
    {
      "activity_id": 4,
      "name": "Peer Feedback",
      "description": "Open discussion on how society exploits Cognitive Dissonance (e.g., insurance advertising, political mobilization). Students give examples and discuss ethical implications.",
      "duration_minutes": 20
    }
  ],
  "assessment_methods": [
    {
      "type": "Formative",
      "method": "Participation and Engagement in Activities",
      "weight": "30%"
    },
    {
      "type": "Summative",
      "method": "Short Essay: 'Analysis of Your Own Cognitive Dissonance' based on assigned scenarios.",
      "weight": "70%"
    }
  ],
  "teacher_notes": [
    "Encourage critical thinking on whether feelings of guilt or anxiety are always present; not all inconsistencies cause dissonance.",
    "Highlight how modern technologies (Social Comparison, Rewarded Choice-marketing) amplify dissonance.",
    "Monitor groups for those who may project their own experiences too heavily into hypothetical analyses.",
    "Remind students that resolving dissonance does not always justify irrational choices."
  ]
}

