      {
        "point": "The War Guilt Clause",
        "description": "Article 231, which forced Germany to accept full responsibility, provided the legal basis for demanding reparations."
      },
      {
        "point": "Economic Reparations",
        "description": "Unpayable financial burden assigned to Germany, leading to hyperinflation, unemployment, and economic instability."
      },
      {
        "point": "Territorial Changes",
        "description": "Loss of significant territory to France and Poland (Alsace-Lorraine, Eupen-Malmedy, Western Silesia), recognizing the right of Belgium and Poland."
      },
      {
        "point": "Military Restrictions",
        "description": "Elimination of conscription, restriction of the army to 100,000, and prohibition of general population mobilization."
      },
      {
        "point": "League of Nations",
        "description": "The establishment of a collective body to maintain international peace, often criticized for its weakness and lack of veto power."
      },
      {
        "point": "Cultural Self-Determination",
        "description": "The principle of bordering nations with the same ethnic majority, leading to the creation of Poland as a 'buffer state' against Germany."
      },
      {
        "point": "French Ambitions",
        "description": "The trauma of modern wars and the desire for a buffer state in the West to ensure the security of France against a resurgent Germany."
      }
