        "materials_needed": [
          "Reprinted excerpts from the Treaty of Versailles (Sections on War Guilt and Reparations) from the end of the 20th-century curriculum text.",
          "A whiteboard and markers."
        ]
      },
      {
        "activity_id": "activity_2",
        "name": "Map of the Map: From 1914 to 1919",
        "description": "Students receive a map showing Europe in 1914 and another in 1919. They must highlight regions lost by Germany, Poland's creation, and the potential buffer states created for France.",
        "materials_needed": [
          "Maps showing 1914 and 1919 Europe.",
          "Highlighters and colored pencils."
        ]
