      {
        "activity_id": "activity_3",
        "name": "Analysis of German Propaganda vs. Allied Statements",
        "description": "Provide students with a short text from a German newspaper blaming the Treaty for 'Gräber der Nation' (Stench of the Nation) versus a BBC article asserting justice. Students write a reaction summary.",
        "materials_needed": [
          "Sample German and British primary sources."
        ]
      }
    ],
    "assessment_methods": [
