        "Aktiven of Frank-Starling Law (Initial compensation via wall stretch)",
        "Neurohormonal activation signaling fails"
      ],
      "mechanism_description": "Impaired contractility and/or diastolic relaxation leads to increased venous pressure and pulmonary/systemic congestion."
    },
    "step_3_compensation_mechanisms": {
      "objective": "Detail the body's immediate physiological responses.",
      "mechanisms": [
        {
          "name": "Sympathetic Nervous System (SNS) Activation",
          "action": "Increase HR, contractility, and vasoconstriction to maintain BP."
        },
        {
          "name": "Renin-Angiotensin-Aldosterone System (RAAS)",
          "action": "Fluid retention, sodium retention, increased vascular tone."
        },
        {
          "name": "Cardiacんfeedback",
          "action": "Upregulation of sodium/hydrogen exchangers and beta-adrenergic receptors."
        }
      ],
      "outcome": "These initially maintain perfusion but eventually increase preload, afterload, and myocardial oxygen demand, leading to maladaptation."
    },
    "step_4_decompensation_dynamics": {
      "objective": "Explain the failure of compensation.",
      "key_points": [
